'use strict';
const D=LocHire;
const icons={wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8h18m-5 5h5v4h-5a2 2 0 0 1 0-4Z"/>',star:'<path d="m12 3 2.8 5.7 6.3.9-4.6 4.5 1.1 6.3-5.6-3-5.6 3 1.1-6.3L3 9.6l6.2-.9Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-9h.01"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12c5 4 13 4 18 0m-9 0v4"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m3-16a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-3-5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',chevron:'<path d="m9 5 7 7-7 7"/>',filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',plus:'<path d="M12 5v14M5 12h14"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/>',tool:'<path d="M14 5a5 5 0 0 0-6 6L3 16a3 3 0 0 0 4 4l5-5a5 5 0 0 0 6-6l-4 4-3-3 4-4Z"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.briefcase}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₦'+Number(n||0).toLocaleString('en-NG');
const initials=s=>String(s||'You').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const KEY='lochire-local-demo-v3';
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==3||!['workers','employers','openings','engagements','reviews','blocks'].every(k=>Array.isArray(state[k])))state=null}catch{}state=state||D.seed();
let searchLocation=null,locationError='',locationPending=false,locationWatch=null;
let role='worker',route={page:'home',id:''},search='',filters={},limit=6,previewActor=null,wizard=null;
const main=document.querySelector('main'),dialog=document.querySelector('dialog');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Browser storage is full or unavailable. This change lasts only until refresh.');return false}}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),4500)}
function ownId(){return role==='worker'?'my-worker':'my-employer'}
function own(){return role==='worker'?state.worker:state.employer}
function workers(){return [...state.workers,...(state.worker?.published?[state.worker]:[])]}
function employers(){return [...state.employers,...(state.employer?[state.employer]:[])]}
function worker(id){return workers().find(x=>x.id===id)||(state.worker?.id===id?state.worker:null)}
function employer(id){return employers().find(x=>x.id===id)}
function opening(id){return state.openings.find(x=>x.id===id)}
function engagement(id){return state.engagements.find(x=>x.id===id)}
function person(id){return worker(id)||employer(id)}
function actor(g){return previewActor&&D.participant(g,previewActor)?previewActor:D.participant(g,ownId())?ownId():null}
function blocked(a,b){return state.blocks.some(x=>(x.actor===a&&x.target===b)||(x.actor===b&&x.target===a))}
function localLabel(p){return `<span class="badge neutral">${p.demo?'Sample demo data':'Your local demo data'}</span>`}
function button(t,a,primary=false,extra=''){return `<button type="button" class="button ${primary?'primary':'secondary'}" data-action="${a}" ${extra}>${t}</button>`}
function go(page,id=''){if(page!=='discover')stopLocationWatch();dialog.close();wizard=null;previewActor=null;route={page,id};location.hash=page+(id?'/'+encodeURIComponent(id):'');render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}
window.addEventListener('lochire:wallet-mode',event=>{role=event.detail;navigation();});
function navigation(){const items=role==='worker'?[['discover','Find work','briefcase'],['engagements','Engagements','calendar'],['messages','Invitations','mail'],['profile','My profile','user']]:[['discover','Find workers','users'],['openings','My openings','briefcase'],['engagements','Engagements','calendar'],['profile','My profile','user']];document.querySelector('#nav').innerHTML=items.map(([p,t,i])=>`<button data-page="${p}" class="${route.page===p?'active':''}" ${route.page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('');document.querySelector('#role-button').innerHTML=icon(role==='worker'?'briefcase':'users')+(role==='worker'?'Finding work':'Hiring')+icon('chevron')}
function render(){navigation();const pages={wallet:()=>LocHireWallet.render(main,{role}),home:home,discover:discover,profile:myProfile,worker:()=>profilePage('worker',route.id),employer:()=>profilePage('employer',route.id),opening:()=>openingPage(route.id),openings:myOpenings,engagements:engagementList,messages:messageList,record:()=>recordPage(route.id),privacy:privacy,guidelines:guidelines,help:help};(pages[route.page]||home)()}
function pageHead(title,desc,action=''){return `<section class="page-top"><div><div class="eyebrow">${role==='worker'?'Your local opportunities':'Your local hiring'}</div><h1>${title}</h1><p>${desc}</p></div>${action}</section>`}
function home(){main.innerHTML=`<section class="hero"><div class="eyebrow">Local people. Everyday work.</div><h1>Find local workers.<br>Find work near you.</h1><p>Connect with artisans and everyday workers for household needs, business roles and one-off tasks.</p><div class="hero-actions"><button class="button primary" data-action="enter-worker">${icon('briefcase')} Find work</button><button class="button primary" data-action="enter-employer">${icon('users')} Hire someone</button></div><p class="caption">Explore a local demo. No real employer or worker is contacted.</p></section><section class="home-categories" aria-label="Popular categories">${D.categories.slice(0,6).map(c=>`<button data-home-category="${esc(c)}">${icon(['Plumbing','Electrical work'].includes(c)?'tool':'home')}<span>${esc(c)}</span></button>`).join('')}</section><section class="nearby-entry"><span>${icon('pin')}</span><div><h2>Find an artisan nearby.</h2><p>Browse plumbers, carpenters, cooks and other local workers by distance and client rating.</p></div><button class="button secondary" data-service="browse-nearby">Find nearby workers</button></section><section class="journey"><h2>A clear next step, for both sides.</h2><p>Create a profile <span>→</span> Find a suitable match <span>→</span> Discuss the work <span>→</span> Confirm the details.</p></section><section class="trust-intro"><span>${icon('shield')}</span><div><h2>Get to know each other.</h2><p>See work experience, the employer’s introduction and clear work details before deciding. Suitability is separate from verification. Checks and live support are not connected in this demo.</p><button class="text-button" data-page="help">How the demo works ${icon('chevron')}</button></div></section>`}
function payText(p,isOpening=false){if(p.quote||p.flexible)return isOpening?'Request a quote':'Price depends on the task';return `${isOpening?money(p.min)+' – '+money(p.max):money(p.pay)} / ${({'Hourly':'hour','Daily':'day','Monthly':'month','Per task':'task'})[p.basis]||'discuss'}`}
function passes(p,isWorker){
  const query=D.norm(search).replace(/\bnear\s+me\b/g,'').trim();
  const aliases={plumber:'plumbing',plumbers:'plumbing',cook:'cooking',cooks:'cooking',carpenter:'carpentry',carpenters:'carpentry',electrician:'electrical work',electricians:'electrical work',cleaner:'cleaning',cleaners:'cleaning',driver:'driving',drivers:'driving'};
  const term=aliases[query]||query;
  if(term&&!D.norm([p.name,p.title,p.occupation,p.category,p.speciality,...D.list(p.skills),p.area,p.city].join(' ')).includes(term))return false;
  if(filters.category&&filters.category!==(p.occupation||p.category))return false;
  if(filters.type&&(isWorker?!p.types?.includes(filters.type):p.type!==filters.type))return false;
  if(filters.city&&D.norm(filters.city)!==D.norm(p.city))return false;
  if(filters.area){const fit=D.norm(p.area).includes(D.norm(filters.area))||(isWorker&&(p.travel||D.list(p.coverage).some(a=>D.norm(a).includes(D.norm(filters.area)))));if(!fit)return false;}
  if(filters.date){const date=isWorker?p.start:(p.type==='One-off task'?p.date:p.start);if(!date||date>filters.date)return false;}
  if(filters.years&&Number(p.years)<Number(filters.years))return false;
  if(filters.budget){const rate=isWorker?p.pay:p.min;if(!filters.basis||p.quote||p.flexible||p.basis!==filters.basis||!rate||Number(rate)>Number(filters.budget))return false;}
  if(isWorker){
    if(filters.available==='yes'&&p.acceptingBookings===false)return false;
    const summary=D.ratingSummary(state,p.id);if(filters.rating&&(!summary.count||summary.average<Number(filters.rating)))return false;
    if(filters.radius&&!D.withinRadius(D.distanceInfo(searchLocation,p.coordinates),Number(filters.radius)))return false;
  }
  return true;
}
function discover(){
 const hiring=role==='employer';
 main.innerHTML=pageHead(hiring?'Find people for the work.':'Find work near you.',hiring?'Find an artisan, read client reviews and request a booking.':'Explore ongoing jobs and one-off local tasks.',hiring?button(icon('plus')+' Post an opening','post',true):'')+
 `<div class="browse-toolbar"><label class="search">${icon('search')}<input id="discovery-search" aria-label="${hiring?'Search workers':'Search openings'}" placeholder="${hiring?'Try plumber near me or cook':'Search local jobs and tasks'}" value="${esc(search)}"></label><button class="filter-button" data-action="filters" aria-label="Filter discovery">${icon('filter')}</button></div>`+
 (hiring?`<section class="nearby-controls" aria-label="Nearby worker search"><div class="nearby-location"><button class="button secondary" data-service="locate-search">${icon('pin')} ${searchLocation?'Update my location':'Use my location'}</button><span id="location-status" role="status"></span></div><div class="discovery-selects"><label>Distance<select id="nearby-radius">${[['','Any distance'],['30','Within 30 m'],['100','Within 100 m'],['500','Within 500 m'],['1000','Within 1 km'],['5000','Within 5 km'],['30000','Within 30 km']].map(([v,t])=>`<option value="${v}" ${String(filters.radius||'')===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Rating<select id="minimum-rating">${[['','Any rating'],['3','3+ stars'],['4','4+ stars'],['5','5 stars']].map(([v,t])=>`<option value="${v}" ${String(filters.rating||'')===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Sort by<select id="worker-sort">${[['relevant','Relevant'],['nearest','Nearest'],['rating','Highest rated']].map(([v,t])=>`<option value="${v}" ${(filters.sort||'relevant')===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="nearby-options"><label><input id="available-workers" type="checkbox" ${filters.available==='yes'?'checked':''}> Accepting bookings</label><label><input id="follow-location" type="checkbox" ${locationWatch!==null?'checked':''}> Update as I move</label>${searchLocation?'<button class="text-button" data-service="forget-location">Clear my location</button>':''}</div><p class="location-note">Distances use voluntarily shared locations. GPS accuracy can limit 30–100 m searches. Sample workers have no live location.</p></section><label class="context-picker">Compare suitability for<select id="compare-opening"><option value="">Browse without comparing</option>${state.openings.filter(o=>o.employerId==='my-employer'&&o.status==='Open').map(o=>`<option value="${esc(o.id)}" ${filters.opening===o.id?'selected':''}>${esc(o.title)}</option>`).join('')}</select></label>`:'')+
 `<div class="section-heading"><h2>${filters.category?esc(filters.category):hiring?'Local workers':'Local openings'}</h2><button class="text-button" data-action="clear-filters">Reset filters</button></div><div id="discovery-list" aria-live="polite"></div>`;
 updateLocationStatus();renderDiscovery();
}
function renderDiscovery(){
 const target=document.querySelector('#discovery-list');if(!target)return;
 const hiring=role==='employer';
 const pool=(hiring?workers():state.openings.filter(o=>o.status==='Open')).filter(p=>!blocked(ownId(),hiring?p.id:p.employerId)&&passes(p,hiring));
 if(hiring&&filters.sort==='rating')pool.sort((a,b)=>{const aa=D.ratingSummary(state,a.id),bb=D.ratingSummary(state,b.id);return (bb.average??-1)-(aa.average??-1)||bb.count-aa.count||a.name.localeCompare(b.name);});
 if(hiring&&filters.sort==='nearest')pool.sort((a,b)=>(D.distanceInfo(searchLocation,a.coordinates)?.metres??Infinity)-(D.distanceInfo(searchLocation,b.coordinates)?.metres??Infinity));
 target.innerHTML=pool.length?`<div class="cards">${pool.slice(0,limit).map(p=>hiring?workerCard(p):openingCard(p)).join('')}</div><div class="list-footer"><span>${Math.min(limit,pool.length)} of ${pool.length} ${hiring?'workers':'openings'}</span>${limit<pool.length?button('Show more','more'):''}</div>`:
 `<div class="empty"><h3>${hiring&&filters.radius&&!searchLocation?'Choose a location to search nearby.':'No results for these filters.'}</h3><p>${hiring&&filters.radius?'Use your location or try a wider radius. Profiles without a recent shared location are excluded; sample workers have no live GPS.':hiring&&filters.rating?'There are no eligible reviews matching this rating yet. Unrated workers are shown when you choose Any rating.':'Try another occupation or area.'}</p>${hiring&&filters.radius&&!searchLocation?'<button class="button primary" data-service="locate-search">Use my location</button>':''}${button('Reset filters','clear-filters')}</div>`;
}
function workerCard(w){const o=opening(filters.opening),m=o?D.suitability(w,o):null;return `<article class="card worker-card"><div class="card-top"><span class="avatar">${esc(initials(w.name))}</span>${localLabel(w)}</div><h3>${esc(w.name)}</h3><p>${esc(w.occupation)} · ${esc(w.speciality)}</p>${ratingBadge(w.id)}<div class="meta">${icon('pin')}${esc(w.area)}, ${esc(w.city)}</div>${distanceBadge(w)}<p class="rate">${payText(w)}</p><p class="booking-availability">${w.acceptingBookings===false?'Not accepting new bookings':'Open to enquiries · Confirm availability'}</p><div class="card-bottom"><span class="caption">${esc(w.years||0)} years · Self-reported</span><button class="text-button" data-worker="${esc(w.id)}">Profile & reviews ${icon('chevron')}</button></div><button class="button secondary booking-button" data-service="book-worker" data-id="${esc(w.id)}" ${w.acceptingBookings===false?'disabled':''}>Request booking</button>${m?`<p class="caption">${esc(m.coverage)}. ${esc(m.budget)}.</p>`:''}</article>`}
function openingCard(o){const e=employer(o.employerId);return `<article class="card"><div class="card-top"><span class="role-symbol">${icon(o.type==='One-off task'?'tool':'briefcase')}</span>${localLabel(o)}</div><h3>${esc(o.title)}</h3><p>${esc(e?.name||'Employer')} · ${esc(e?.type||'')}</p><div class="meta">${icon('pin')}${esc(o.area)}, ${esc(o.city)}</div><p class="rate">${payText(o,true)}</p><div class="card-bottom"><span class="caption">${esc(o.type)}</span><button class="text-button" data-opening="${esc(o.id)}">View opening ${icon('chevron')}</button></div></article>`}
function modal(title,desc,body){if(dialog.open)dialog.close();document.querySelector('#dialog-content').innerHTML=`<div class="modal-body"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><p>${desc}</p>${body}</div>`;dialog.showModal()}
function roleModal(){modal('One person. Two ways to use LocHire.','You can find work and hire someone using separate profiles.',`<div class="modal-menu">${button(icon('briefcase')+' Find work','enter-worker',true)}${button(icon('users')+' Hire someone','enter-employer',true)}</div>`)}
function field(n,l,v='',type='text',extra=''){return `<div class="field"><label for="f-${n}">${l}</label><input id="f-${n}" name="${n}" value="${esc(v)}" type="${type}" ${extra}></div>`}
function textArea(n,l,v='',required=true){return `<div class="field"><label for="f-${n}">${l}</label><textarea id="f-${n}" name="${n}" maxlength="1500" ${required?'required':''}>${esc(v)}</textarea></div>`}
function select(n,l,options,v,req=true){return `<div class="field"><label for="f-${n}">${l}</label><select id="f-${n}" name="${n}" ${req?'required':''}>${options.map(x=>{const [key,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(key)}" ${key===v?'selected':''}>${esc(label)}</option>`}).join('')}</select></div>`}
function check(n,l,checked=false){return `<label class="check-field"><input type="checkbox" name="${n}" ${checked?'checked':''}><span>${l}</span></label>`}
function multi(n,label,values,chosen=[]){return `<fieldset class="multi"><legend>${label}</legend>${values.map(v=>`<label><input type="checkbox" name="${n}" value="${esc(v)}" ${chosen.includes(v)?'checked':''}><span>${esc(v)}</span></label>`).join('')}</fieldset>`}
function formError(t){const e=document.querySelector('#form-error');if(e){e.textContent=t;e.focus()}else toast(t)}
function errorBox(){return '<p id="form-error" role="alert" tabindex="-1"></p>'}
function filterModal(){const f=filters;modal('Narrow your search','All fields are optional. Unknown availability and prices are not treated as confirmed.',`<form id="filters-form">${select('category','Occupation / service',[['','Any'],...D.categories],f.category||'',false)}${select('type','Type of work',[['','Both'],'Ongoing job','One-off task'],f.type||'',false)}<div class="two-fields">${field('city','City',f.city,'text','maxlength="70"')}${field('area','Area / coverage',f.area,'text','maxlength="70"')}</div>${field('date','Available / starts by',f.date,'date')}${field('years','Minimum experience in years',f.years,'number','min="0" max="60"')}<div class="two-fields">${field('budget','Maximum rate / budget (₦)',f.budget,'number','min="0" max="100000000"')}${select('basis','Compare payment basis',[['','Choose'],...D.bases],f.basis||'',false)}</div>${errorBox()}<div class="modal-actions">${button('Cancel','close')}<button class="button primary">Apply filters</button></div></form>`)}
function trustPanel(p){return `<section class="panel"><h2>Checks, not promises.</h2><p class="caption">Information is self-reported. No verification service is connected.</p><div class="checks">${['Phone confirmed','Identity checked','References checked',...(p.type==='Business'?['Business checked']:[])].map(t=>`<div><span>${t}</span><strong>Not checked</strong></div>`).join('')}</div></section>`}
function reviewsPanel(id){const rr=D.eligibleReviews(state,id),summary=D.ratingSummary(state,id);return `<section class="panel" id="work-reviews"><h2>Ratings & client reviews</h2><div class="rating-overview">${ratingBadge(id)}<span class="caption">Only participants in completed local engagements can review.</span></div>${rr.length?rr.slice().reverse().map(r=>{const g=engagement(r.engagementId);return `<article class="review"><div class="review-heading"><strong>${esc(person(r.author)?.name||'A participant')}</strong>${stars(r.rating)}<span>${r.rating} / 5</span></div><p>${esc(r.text)}</p><span class="caption">${esc(g.title)} · ${esc(g.type)} · Completed local demo${r.at?' · '+new Date(r.at).toLocaleDateString('en-NG',{timeZone:'Africa/Lagos'}):''}</span></article>`;}).join(''):'<p>No reviews yet. A new worker is shown as unrated.</p>'}</section><section class="panel"><h2>Completed work</h2>${completedWorkHistory(id)}</section>`}
function safeActions(id,type){return `<div class="safety-actions"><button class="text-button" data-report="${esc(id)}" data-report-type="${type}">Report ${type}</button><button class="text-button" data-block="${esc(id)}">${state.blocks.some(b=>b.actor===ownId()&&b.target===id)?'Unblock':'Block unwanted contact'}</button><button class="text-button" data-page="help">Request support</button></div>`}
function profilePage(kind,id){const raw=kind==='worker'?worker(id):employer(id);if(!raw){notFound();return}const p=D.publicProfile(raw),isMine=id===ownId();main.innerHTML=`<button class="back" data-page="discover">${icon('chevron')} Back to discovery</button>`+pageHead(esc(p.name),`${esc(kind==='worker'?p.occupation:p.type)} · ${esc(p.area)}, ${esc(p.city)}`)+`<div class="profile-columns"><div><section class="panel">${localLabel(p)}${kind==='worker'?ratingBadge(id)+distanceBadge(raw):''}<h2>${kind==='worker'?'What I can offer':'About this employer'}</h2><p>${esc(kind==='worker'?p.experience:p.intro)}</p>${kind==='worker'?detailsGrid([['Speciality',p.speciality],['Skills / services',D.list(p.skills).join(', ')],['Experience',p.years+' years (self-reported)'],['Work types',p.types?.join(', ')],['Working days',p.days?.join(', ')],['Working hours',`${p.hoursStart||'?'} – ${p.hoursEnd||'?'} WAT`],['Earliest start',p.start||'Not specified'],['Areas covered',D.list(p.coverage).join(', ')],['Travel',p.travel?'Willing to discuss travel':'Within listed areas'],['Expected pay',payText(p)],...(D.domestic.includes(p.occupation)?[['Accommodation',p.accommodation]]:[]),...(p.occupation==='Driving'?[['Driving licence',p.licence||'Not specified; not checked']]:[])])+`<h3>Previous work (optional)</h3><p>${esc(p.workExample||'No example added.')}</p>`:p.type==='Business'?`<h3>Business information</h3><p>${esc(p.business)}</p>`:''}</section>${kind==='worker'&&filters.opening?matchPanel(p,opening(filters.opening)):''}${kind==='employer'?`<section class="panel"><h2>Active openings</h2><div class="stack">${state.openings.filter(o=>o.employerId===id&&o.status==='Open').map(o=>`<button class="list-row" data-opening="${esc(o.id)}"><span>${esc(o.title)}<small>${esc(o.type)}</small></span>${icon('chevron')}</button>`).join('')||'<p>No active openings.</p>'}</div><h3>Hiring history</h3><p>${state.engagements.filter(g=>g.employerId===id&&g.status==='Completed').length} completed local demo engagements. No live history is connected.</p></section>`:''}${reviewsPanel(id)}</div><aside>${trustPanel(p)}<section class="panel"><h2>Private contact details</h2><p>${isMine?'Only shown in your own local profile editor.':'Not shown on public profiles. An email is usable only when its owner chooses to share it; sample profiles have no contact details.'}</p>${kind==='worker'&&!isMine?`<div class="profile-booking-actions"><button class="button primary" data-service="book-worker" data-id="${esc(id)}" ${raw.acceptingBookings===false?'disabled':''}>Request booking</button>${button('Discuss work / invite','contact-worker',false,`data-id="${esc(id)}"`)}<button class="button secondary" data-service="email-worker" data-id="${esc(id)}">${icon('mail')} Compose email enquiry</button></div><p class="caption">Booking requests need the worker’s response and agreed work details. Email opens your own mail app.</p>`:''}${kind==='employer'&&!isMine?'<p class="caption">View an opening to start a local demo conversation.</p>':''}</section>${kind==='worker'&&isMine?workerLocationPanel():''}${!isMine?safeActions(id,'profile'):''}</aside></div>`}
function detailsGrid(items){return `<dl class="detail-grid">${items.map(([l,v])=>`<div><dt>${esc(l)}</dt><dd>${esc(v||'Not yet specified')}</dd></div>`).join('')}</dl>`}
function matchPanel(w,o){if(!o)return '';const m=D.suitability(w,o);return `<section class="panel"><h2>Suitability for this work</h2><p class="caption">Job-related information only. This is not a reliability score or verification.</p><ul class="match-list">${[m.skills,m.coverage,m.budget,m.schedule,m.typeFit?'Worker is interested in this type of work':'Work type needs discussing',m.experience?'Listed experience meets the requested years':'Experience requirement needs discussing'].map(t=>`<li>${icon('info')}<span>${esc(t)}</span></li>`).join('')}</ul></section>`}
function openingPage(id){const o=opening(id);if(!o){notFound();return}const e=employer(o.employerId);main.innerHTML=`<button class="back" data-page="discover">${icon('chevron')} Back to discovery</button>`+pageHead(esc(o.title),`${esc(o.type)} · ${esc(o.area)}, ${esc(o.city)}`)+`<div class="profile-columns"><div><section class="panel">${localLabel(o)}<span class="badge">${esc(o.status)}</span><h2>Work to be done</h2><p>${esc(o.description)}</p>${detailsGrid([['Budget / pay',payText(o,true)],['Payment basis',o.basis],['Required skills',D.list(o.skills).join(', ')],['Relevant experience',o.years+' years requested'],...(o.type==='One-off task'?[['Preferred date',o.date||'To discuss'],['Estimated duration',o.duration],['Materials',o.materials]]:[['Working days',o.days.join(', ')],['Hours',o.hoursStart+' – '+o.hoursEnd+' WAT'],['Start date',o.start],['Accommodation',o.accommodation]])])}${window.LocHirePostcode?.summary(o.jobLocation,role==='employer'&&o.employerId===ownId())||''}${o.photos?.length?`<div class="photo-grid">${o.photos.filter(validPhoto).map((src,i)=>`<img src="${esc(src)}" alt="Work photo ${i+1}, provided by the employer">`).join('')}</div>`:''}</section>${state.worker&&role==='worker'?matchPanel(state.worker,o):''}</div><aside><section class="panel"><h2>Meet the employer</h2><h3>${esc(e?.name)}</h3><p>${esc(e?.intro)}</p><p class="caption">${esc(e?.type)} · Self-reported · Checks not connected.</p><button class="button secondary" data-employer="${esc(e?.id)}">View employer profile</button></section><section class="panel"><h2>Discuss before deciding.</h2><p>Agree the scope, pay and schedule together. No payment protection or insurance is provided.</p>${o.status==='Open'&&role==='worker'?button(o.type==='One-off task'?'Discuss task / request quote':'Express interest / ask a question','contact-opening',true,`data-id="${esc(id)}"`):''}${o.employerId===ownId()?button('Edit opening','edit-opening',false,`data-id="${esc(id)}"`):''}</section>${safeActions(o.employerId,'profile')}<button class="text-button" data-report="${esc(id)}" data-report-type="opening">Report this opening</button></aside></div>`}
function myProfile(){const p=own();main.innerHTML=pageHead(role==='worker'?'Your work profile.':'Your employer profile.',role==='worker'?'Show what you do and where you can work.':'Individuals, households and businesses are welcome. No company name is needed for a household.',button(p?'Edit profile':'Create profile','edit-profile',true))+`${p?`<section class="profile-overview"><span class="avatar">${esc(initials(p.name))}</span><h2>${esc(p.name)}</h2><p>${esc(role==='worker'?p.occupation:p.type)} · ${esc(p.area)}, ${esc(p.city)}</p>${localLabel(p)}</section><div class="settings-menu"><button data-page="wallet">${icon('wallet')}<span>Wallet & payments<small>Saved account, test balance and receipts</small></span>${icon('chevron')}</button><button data-action="own-preview">${icon('user')}<span>View public profile</span>${icon('chevron')}</button>${role==='worker'?`<button data-action="visibility">${icon('users')}<span>Visibility<small>${p.published?'Visible in local demo discovery':'Hidden from discovery'}</small></span>${icon('chevron')}</button>`:''}<button data-action="blocked-list">${icon('shield')}<span>Blocked profiles</span>${icon('chevron')}</button><button data-page="privacy">${icon('shield')}<span>Private contact details and demo privacy</span>${icon('chevron')}</button></div>`:`<div class="empty"><h3>Start with a short introduction.</h3><p>Your profile form is split into small steps. Contact details stay out of public profile views.</p>${button('Create my profile','edit-profile',true)}</div>`}${p&&role==='worker'?workerLocationPanel():''}<button class="button secondary" data-page="wallet">Open wallet & payments</button><p class="note">Your hiring-profile entries are local demo data. Use fictional contact details on a shared device. There is no login or security boundary between people using this browser.</p>`}
function profileWizard(){const existing=own();wizard={kind:role,step:0,draft:D.clone(existing|| (role==='worker'?{id:'my-worker',name:'',email:'',phone:'',city:'Lagos',area:'',occupation:'Domestic help',speciality:'',skills:[],years:0,experience:'',days:['Mon','Tue','Wed','Thu','Fri'],hoursStart:'08:00',hoursEnd:'17:00',start:D.today(),coverage:[],travel:false,types:['Ongoing job'],pay:'',basis:'Monthly',flexible:false,accommodation:'Live-out',workExample:'',licence:'Not specified',published:true,demo:false}:{id:'my-employer',name:'',type:'Household',city:'Lagos',area:'',intro:'',email:'',phone:'',business:'',demo:false}))};wizardPage()}
function wizardPage(){const w=wizard;if(!w)return;const d=w.draft,isWorker=w.kind==='worker',isEmployer=w.kind==='employer',isPost=w.kind==='opening';let body='',labels=isWorker?['Introduction','Work and skills','Availability','Pay and review']:isEmployer?['Who you are','Contact and review']:['Type of help','Work details','Practical details','Review'];if(isWorker){if(w.step===0)body=field('name','Name',d.name,'text','required maxlength="70" autocomplete="name"')+field('email','Private email',d.email,'email','required maxlength="254" autocomplete="email"')+field('phone','Private phone',d.phone,'tel','required maxlength="30" autocomplete="tel"')+locationFields(d);if(w.step===1)body=select('occupation','Main occupation',D.categories,d.occupation)+field('speciality','Specific speciality',d.speciality,'text','required maxlength="100" placeholder="e.g. leak repairs, Nigerian meals or home laundry"')+field('skills','Other skills / services (comma separated)',D.list(d.skills).join(', '),'text','maxlength="300"')+field('years','Relevant experience (years)',d.years,'number','required min="0" max="60"')+textArea('experience','Tell us about your experience',d.experience)+ (d.occupation==='Driving'?select('licence','Driving licence (self-reported)', ['Not specified','I have a valid licence (not checked)','I do not have a valid licence'],d.licence):'');if(w.step===2)body=multi('types','Interested in', ['Ongoing job','One-off task'],d.types)+multi('days','Working days',D.days,d.days)+`<div class="two-fields">${field('hoursStart','Available from (WAT)',d.hoursStart,'time','required')}${field('hoursEnd','Available until (WAT)',d.hoursEnd,'time','required')}</div>`+field('start','Earliest start date',d.start,'date','required')+field('coverage','Areas covered (comma separated)',D.list(d.coverage).join(', '),'text','required maxlength="300"')+check('travel','Willing to discuss travel outside those areas',d.travel);if(w.step===3)body=check('flexible','Price depends on the task',d.flexible)+field('pay','Expected pay (₦)',d.pay,'number',`min="0" max="100000000" ${d.flexible?'':'required'}`)+select('basis','Payment basis',D.bases,d.basis)+(D.domestic.includes(d.occupation)?select('accommodation','Live-in / live-out preference',['Live-out','Live-in','Either, after discussing'],d.accommodation):'')+textArea('workExample','Examples of previous work (optional)',d.workExample,false)+check('contactEmailShared','Allow people viewing this local profile to use my email for an enquiry',d.contactEmailShared)+`<p class="note">References, phone and identity are not checked. Do not upload identity documents or other people’s private contact details.</p><details><summary>Review your earlier details</summary>${detailsGrid([['Name',d.name],['General location',d.area+', '+d.city],['Occupation',d.occupation+' · '+d.speciality],['Experience',d.experience],['Availability',d.days.join(', ')+' '+d.hoursStart+' – '+d.hoursEnd],['Work types',d.types.join(', ')]])}</details>`;}
if(isEmployer){if(w.step===0)body=select('type','Employer type',['Individual','Household','Business'],d.type)+field('name','Display name',d.name,'text','required maxlength="90" placeholder="e.g. Ada O. or The Okafor household"')+locationFields(d)+textArea('intro','Short introduction',d.intro);if(w.step===1)body=field('email','Private email',d.email,'email','required maxlength="254"')+field('phone','Private phone',d.phone,'tel','required maxlength="30"')+(d.type==='Business'?textArea('business','Business details (self-reported)',d.business):'')+detailsGrid([['Display name',d.name],['Employer type',d.type],['General location',d.area+', '+d.city],['Introduction',d.intro]])+'<p class="note">Business, phone and identity checks are not connected. No completed verification badge will be shown.</p>';}
if(isPost){if(w.step===0)body=select('type','What kind of help do you need?',['One-off task','Ongoing job'],d.type)+select('category','Service / occupation',D.categories,d.category);if(w.step===1)body=field('title','Opening title',d.title,'text','required maxlength="100"')+textArea('description',d.type==='One-off task'?'Describe the problem / work':'Role and responsibilities',d.description)+locationFields(d)+(window.LocHirePostcode?.field(d.jobLocation)||'')+field('skills','Required skills (comma separated)',D.list(d.skills).join(', '),'text',`${d.type==='Ongoing job'?'required':''} maxlength="300"`)+field('years','Required relevant experience (years)',d.years,'number','min="0" max="60"');if(w.step===2)body=(d.type==='One-off task'?field('date','Preferred date',d.date,'date',`required min="${D.today()}"`)+field('duration','Estimated duration',d.duration,'text','required maxlength="100" placeholder="e.g. a few hours, to confirm after inspection"')+select('materials','Materials arrangements',['Discuss together','Employer supplies materials','Worker supplies, agree cost first'],d.materials)+check('quote','Request a quote instead of a fixed budget',d.quote)+`<div class="two-fields">${field('min','Minimum budget (₦)',d.min,'number',`min="0" max="100000000" ${d.quote?'':'required'}`)}${field('max','Maximum budget (₦)',d.max,'number',`min="0" max="100000000" ${d.quote?'':'required'}`)}</div>`+select('basis','Budget basis',D.bases,d.basis)+`<div class="field"><label for="task-photos">Optional photos (up to 2, PNG/JPEG/WebP, 1 MB each)</label><input id="task-photos" name="photos" type="file" accept="image/png,image/jpeg,image/webp" multiple></div>${d.photos?.length?'<p class="caption">'+d.photos.length+' photos attached. New files replace these.</p>'+check('removePhotos','Remove attached photos'):''}`:multi('days','Working days',D.days,d.days)+`<div class="two-fields">${field('hoursStart','Work starts (WAT)',d.hoursStart,'time','required')}${field('hoursEnd','Work ends (WAT)',d.hoursEnd,'time','required')}</div>`+field('start','Start date',d.start,'date',`required min="${D.today()}"`)+`<div class="two-fields">${field('min','Minimum salary / pay (₦)',d.min,'number','required min="1" max="100000000"')}${field('max','Maximum salary / pay (₦)',d.max,'number','required min="1" max="100000000"')}</div>`+select('basis','Payment frequency',['Hourly','Daily','Monthly'],d.basis)+(D.domestic.includes(d.category)?select('accommodation','Live-in / live-out arrangements',['Live-out','Live-in','Discuss together'],d.accommodation):''));if(w.step===3)body=`<h3>${esc(d.title)}</h3>${detailsGrid([['Employer',state.employer.name+' · '+state.employer.type],['Type',d.type],['Category',d.category],['General location',d.area+', '+d.city],['Work',d.description],['Pay',payText(d,true)],['Skills',D.list(d.skills).join(', ')],...(d.type==='One-off task'?[['Date',d.date],['Duration',d.duration],['Materials',d.materials]]:[['Days',d.days.join(', ')],['Hours',d.hoursStart+' – '+d.hoursEnd+' WAT'],['Start',d.start],['Accommodation',d.accommodation]])])}${window.LocHirePostcode?.summary(d.jobLocation,true)||''}<p class="note">This opening will be saved on this device only. It is not published to real workers.</p>`;}
main.innerHTML=`<section class="form-page"><button class="back" data-action="cancel-wizard">${icon('close')} Cancel without saving</button><div class="eyebrow">${isPost?'Post an opening':isWorker?'Worker profile':'Employer profile'} · Step ${w.step+1} of ${labels.length}</div><h1>${labels[w.step]}</h1><p class="caption">Short steps. Private contacts. Local demo only.</p><div class="progress" aria-label="Step ${w.step+1} of ${labels.length}">${labels.map((l,i)=>`<span class="${i<=w.step?'filled':''}"></span>`).join('')}</div><form id="wizard-form">${body}${errorBox()}<div class="form-actions">${w.step?button('Back','wizard-back'):button('Cancel','cancel-wizard')}<button class="button primary" type="submit">${w.step===labels.length-1?(isPost?'Save opening':'Save profile'):'Continue'}</button></div></form></section>`;main.focus({preventScroll:true});if(isPost)window.LocHirePostcode?.mount(document.querySelector('#wizard-form'));}
function locationFields(d){return `<div class="two-fields">${field('city','City',d.city,'text','required maxlength="70"')}${field('area','General area',d.area,'text','required maxlength="90" placeholder="e.g. Yaba, not a home address"')}</div>`}
function validPhoto(src){return /^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(src)}
async function submitWizard(f){const w=wizard;if(!w)return;const fd=new FormData(f),d={...w.draft};for(const [k,v]of fd){if(['days','types','photos'].includes(k))continue;d[k]=typeof v==='string'?v.trim():v}for(const k of ['days','types'])if(f.querySelector(`[name="${k}"]`))d[k]=fd.getAll(k);for(const k of ['travel','flexible','quote','contactEmailShared'])if(f.querySelector(`[name="${k}"]`))d[k]=fd.has(k);for(const k of ['skills','coverage'])if(k in d)d[k]=D.list(d[k]);for(const k of ['years','pay','min','max'])if(k in d)d[k]=Number(d[k]||0);
if(w.kind==='worker'){if(w.step===1&&(!d.speciality||!d.experience))throw Error('Add your speciality and relevant experience.');if(w.step===2&&(!d.days.length||!d.types.length||d.hoursEnd<=d.hoursStart))throw Error('Choose working days, work types and hours ending after they start.');if(d.occupation==='Driving'&&w.step===1&&!('licence' in Object.fromEntries(fd)))d.licence='Not specified';if(!D.domestic.includes(d.occupation))d.accommodation='Not applicable';}
if(w.kind==='opening'){if(w.step===1&&window.LocHirePostcode)d.jobLocation=LocHirePostcode.collect(f);if(w.step===0&&d.type!==w.draft.type){d.quote=false;d.photos=[];d.basis=d.type==='One-off task'?'Per task':'Monthly'}if(w.step===2){if(fd.has('removePhotos'))d.photos=[];const files=fd.getAll('photos').filter(x=>x instanceof File&&x.size);if(files.length){if(files.length>2||files.some(x=>x.size>1048576||!['image/png','image/jpeg','image/webp'].includes(x.type)))throw Error('Use up to two PNG, JPEG or WebP photos, at most 1 MB each.');d.photos=await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read the photo.'));r.readAsDataURL(file)})))}D.validateOpening(d)}if(!D.domestic.includes(d.category))d.accommodation='Not applicable';if(d.type==='Ongoing job'){d.quote=false;d.photos=[];d.materials='Not applicable'}}
const last=w.kind==='employer'?1:3;if(w.step===last){if(w.kind==='opening'){D.validateOpening(d);d.employerId='my-employer';d.demo=false;d.status=d.status||'Open';const idx=state.openings.findIndex(x=>x.id===d.id);if(idx>=0){if(state.openings[idx].employerId!=='my-employer')throw Error('Only your openings can be edited.');state.openings[idx]=d}else state.openings.unshift(d);save();wizard=null;go('openings');toast('Opening saved locally. No workers were notified.')}else{D.validateProfile(d,w.kind);d.demo=false;if(w.kind==='worker')state.worker=d;else state.employer=d;save();wizard=null;go('profile');toast('Profile saved locally. Contacts remain out of public views.')}}else{w.draft=d;w.step++;wizardPage();window.scrollTo({top:0,behavior:'instant'})}}
function ensureProfile(which){const p=which==='worker'?state.worker:state.employer;if(p)return true;modal('Create your '+which+' profile first.','Your name and general location help the other side understand who they are talking to.',button('Create profile','required-profile',true,`data-role="${which}"`));return false}
function postWizard(id){if(role!=='employer'){toast('Switch to Hiring to post an opening.');return}if(!ensureProfile('employer'))return;const existing=opening(id);if(existing&&existing.employerId!=='my-employer'){toast('Only your own openings can be edited.');return}wizard={kind:'opening',step:0,draft:D.clone(existing||{id:D.uid(),employerId:'my-employer',type:'One-off task',category:'Plumbing',title:'',description:'',city:state.employer.city,area:state.employer.area,date:'',duration:'',start:D.today(),days:['Mon','Tue','Wed','Thu','Fri'],hoursStart:'09:00',hoursEnd:'17:00',min:0,max:0,basis:'Per task',quote:false,skills:[],years:0,materials:'Discuss together',accommodation:'Live-out',photos:[],status:'Open',demo:false})};wizardPage()}
function myOpenings(){if(role!=='employer'){role='employer';navigation()}const list=state.openings.filter(o=>o.employerId==='my-employer');main.innerHTML=pageHead('Your openings.','Post a task or an ongoing role. Edit or change its status at any time.',button(icon('plus')+' Post an opening','post',true))+`${list.length?`<div class="stack">${list.map(o=>`<article class="panel"><span class="badge ${o.status==='Closed'?'neutral':''}">${o.status}</span><h2>${esc(o.title)}</h2><p>${esc(o.type)} · ${esc(o.area)} · ${payText(o,true)}</p><div class="row-actions"><button class="button secondary" data-opening="${esc(o.id)}">View opening</button>${button('Edit','edit-opening',false,`data-id="${esc(o.id)}"`)}${button(o.status==='Open'?'Close':'Reopen','opening-status',false,`data-id="${esc(o.id)}"`)}</div></article>`).join('')}</div>`:`<div class="empty"><h3>What kind of help do you need?</h3><p>Start with a one-off task or an ongoing job.</p>${button('Post your first opening','post',true)}</div>`}`}
function contactWorker(id){if(role!=='employer'){toast('Switch to Hiring to invite a worker.');return}if(!ensureProfile('employer'))return;const ww=worker(id),oo=state.openings.filter(o=>o.employerId==='my-employer'&&o.status==='Open');if(!ww||blocked(ownId(),id)){toast('Contact is blocked.');return}if(!oo.length){modal('Post an opening first.','An opening helps the worker understand what you need before responding.',button('Post an opening','post',true));return}modal('Start a conversation with '+esc(ww.name),'The worker can review your employer profile before responding. This invitation is local only.',`<form id="contact-worker-form" data-worker="${esc(id)}">${select('opening','Choose your opening',oo.map(o=>[o.id,o.title]),filters.opening||oo[0].id)}${textArea('message','Introduce the work / interview invitation','')}${field('date','Optional conversation date (WAT)','','date',`min="${D.today()}"`)}${field('time','Optional conversation time (WAT)','','time')}${errorBox()}<div class="modal-actions">${button('Cancel','close')}<button class="button primary">Create demo invitation</button></div></form>`)}
function contactOpening(id){if(role!=='worker'){toast('Switch to Finding work to discuss this opening.');return}if(!ensureProfile('worker'))return;const o=opening(id),e=employer(o?.employerId);if(!o||o.status!=='Open'||blocked(ownId(),o.employerId)){toast('This opening is unavailable or contact is blocked.');return}modal(o.type==='One-off task'?'Discuss this task':'Express interest',`${esc(e.name)} can review your profile. This message stays in this browser.`, `<form id="contact-opening-form" data-opening="${esc(id)}">${textArea('message',o.type==='One-off task'?'Ask about scope, materials or a quote':'Introduce yourself or ask about the role','')}${errorBox()}<div class="modal-actions">${button('Cancel','close')}<button class="button primary">Start demo conversation</button></div></form>`)}
function startContact(o,w,e,initiator,message,date,time,kind){if(blocked(w.id,e.id))throw Error('Contact is blocked between these profiles.');if(state.engagements.some(g=>g.openingId===o.id&&g.workerId===w.id&&g.employerId===e.id&&!['Declined','Cancelled','Completed'].includes(g.status)))throw Error('An active conversation already exists. Open My engagements.');if(!message?.trim())throw Error('Add a message about the work.');if((date&&!time)||(!date&&time))throw Error('Add both the conversation date and time, or leave both empty.');if(date&&new Date(`${date}T${time}:00+01:00`)<=new Date())throw Error('Choose a future conversation time in WAT.');const g=D.createEngagement(o,w,e,initiator,o.type==='One-off task'?'Task discussion':initiator===e.id?'Interview invitation':'Interest in ongoing work');if(kind)g.kind=kind;g.conversation=date?{date,time}:null;D.addMessage(g,initiator,message);state.engagements.unshift(g);save();go('record',g.id);toast('Conversation created locally. No message or email was sent.')}
function engagementList(){const pool=state.engagements.filter(g=>D.participant(g,ownId()));main.innerHTML=pageHead('My engagements.','Follow conversations, agreed details and completed work.')+(pool.length?`<div class="stack">${pool.map(g=>recordCard(g)).join('')}</div>`:`<div class="empty"><h3>No engagements yet.</h3><p>${role==='worker'?'Open a job or task to discuss the work.':'Post an opening, then view a worker profile to invite them.'}</p><button class="button primary" data-page="discover">${role==='worker'?'Find work':'Find workers'}</button></div>`)}
function recordCard(g){return `<button class="list-row record-card" data-record="${esc(g.id)}"><span><span class="badge ${['Cancelled','Declined'].includes(g.status)?'neutral':''}">${g.status}</span><strong>${esc(g.title)}</strong><small>${esc(person(D.other(g,ownId()))?.name)} · ${esc(g.type)} · Local demo</small></span>${icon('chevron')}</button>`}
function messageList(){const pool=state.engagements.filter(g=>D.participant(g,ownId()));main.innerHTML=pageHead('Messages and invitations.','A local conversation inbox. No message is delivered to another device.')+(pool.length?`<div class="stack">${pool.map(g=>recordCard(g)).join('')}</div>`:'<div class="empty"><h3>Your inbox is clear.</h3><p>Start a conversation from an opening or review invitations in My engagements.</p></div>')}
function recordPage(id){const g=engagement(id);if(!g||!D.participant(g,ownId())){notFound();return}const a=actor(g),other=D.other(g,a),p=person(other),isBlocked=blocked(a,other);main.innerHTML=`<button class="back" data-page="engagements">${icon('chevron')} My engagements</button>`+pageHead(esc(g.title),`${esc(g.kind)} · ${esc(g.type)} · Local demo`)+`<div class="simulation-bar"><div><strong>${previewActor?'Previewing the other party':'Your '+(a===g.workerId?'worker':'employer')+' view'}</strong><p>${previewActor?esc(person(a)?.name)+' - simulated response, not a real account.':'You can preview the counterpart to test both sides on this device.'}</p></div>${button(previewActor?'Return to my view':'Preview other party in demo','preview-party',false,`data-id="${esc(id)}"`)}</div><div class="profile-columns"><div><section class="panel"><span class="badge ${['Cancelled','Declined'].includes(g.status)?'neutral':''}">${g.status}</span><h2>Before you decide</h2><p>${g.status==='Pending'?'The invited party can accept, decline or ask a question after reviewing the other profile.':g.status==='Accepted'?'Discuss the work and propose details. Both sides must confirm the same version.':g.status==='Confirmed'?'Both sides confirmed this version. Mark work completed only after it is done.':g.status==='Completed'?'Both sides marked the work completed in this demo. Eligible participants can leave reviews.':'This engagement is closed.'}</p><div class="row-actions"><button class="button secondary" ${a===g.workerId?'data-employer':'data-worker'}="${esc(other)}">View ${a===g.workerId?'employer':'worker'} profile</button>${!isBlocked&&g.status==='Pending'&&a!==g.initiator?button('Accept conversation','accept',true,`data-id="${esc(id)}"`)+button('Decline','decline',false,`data-id="${esc(id)}"`):''}</div>${!isBlocked&&g.status==='Accepted'&&g.type==='Ongoing job'?button('Arrange a conversation','arrange-conversation',false,`data-id="${esc(id)}"`):''}${g.conversation?`<p class="note">Proposed conversation: ${esc(g.conversation.date)} at ${esc(g.conversation.time)} WAT. Discuss changes in the thread.</p>`:''}</section>${window.LocHirePostcode?.summary(g.jobLocation,a===g.employerId||['Accepted','Confirmed','Completed'].includes(g.status))||''}${workDetails(g,a,isBlocked)}<section class="panel"><h2>Conversation</h2><p class="caption">Local messages only. No contact details are automatically exposed or emails sent.</p><div class="messages">${g.messages.map(m=>`<article class="message ${m.actor===a?'mine':''}"><strong>${esc(person(m.actor)?.name)} ${m.actor===a?'(this view)':''}</strong><p>${esc(m.text)}</p><small>${new Date(m.at).toLocaleString('en-NG',{timeZone:'Africa/Lagos'})} WAT</small></article>`).join('')||'<p>No messages yet.</p>'}</div>${!isBlocked&&!['Cancelled','Declined','Completed'].includes(g.status)?`<form id="message-form" data-id="${esc(id)}">${textArea('message','Ask a question / discuss the work','')}${errorBox()}<button class="button primary">Save local message</button></form>`:`<p class="note">${isBlocked?'Contact is blocked. Unblock from My profile to continue.':'This conversation is closed.'}</p>`}</section><section class="panel"><h2>Activity record</h2><ul class="activity">${g.history.map(h=>`<li>${esc(h.text.replaceAll(g.workerId,worker(g.workerId)?.name||'worker').replaceAll(g.employerId,employer(g.employerId)?.name||'employer'))}</li>`).join('')}</ul></section></div><aside><section class="panel"><h2>Payment for this work</h2><p>Use the wallet to create a server-saved payment agreement. The real recipient must supply their wallet ID and accept the work details.</p><button type="button" class="button secondary" data-wallet-local-record="${esc(g.id)}">Create payment agreement</button><h2>Keep the next step clear.</h2><p>This is a record of agreed work details, not insurance, escrow, payment protection or a legal guarantee.</p>${!['Completed','Cancelled','Declined'].includes(g.status)?button('Cancel engagement','cancel-engagement',false,`data-id="${esc(id)}"`):''}</section>${g.status==='Completed'?reviewPanel(g,a):''}${safeActions(other,'profile')}</aside></div>`}
function workDetails(g,a,stop){const t=g.terms;return `<section class="panel"><h2>Agreed work details ${t?'<span class="caption">Version '+g.version+'</span>':''}</h2>${t?detailsGrid([['Scope / responsibilities',t.scope],['Pay',money(t.pay)+' / '+t.basis],['Schedule',t.schedule],['Start date',t.start],['Completion date',t.completionDate||'Ongoing'],['General location',t.area+', '+t.city],['Materials / accommodation',t.arrangements||'Not applicable'],['Worker confirmation',g.confirmations[g.workerId]===g.version?'Confirmed version '+g.version:'Pending'],['Employer confirmation',g.confirmations[g.employerId]===g.version?'Confirmed version '+g.version:'Pending']]):'<p>No details proposed yet. Accept the conversation, then agree the work scope and pay.</p>'}${!stop&&['Accepted','Confirmed'].includes(g.status)?`<div class="row-actions">${button(t?'Propose changed details':'Propose work details','terms',false,`data-id="${esc(g.id)}"`)}${g.status==='Accepted'&&t&&g.confirmations[a]!==g.version?button('Confirm version '+g.version,'confirm-terms',true,`data-id="${esc(g.id)}" data-version="${g.version}"`):''}${g.status==='Confirmed'?g.completion[a]?'<p class="caption">Your completion is recorded. Waiting for the other side.</p>':button('Mark my side completed','complete',true,`data-id="${esc(g.id)}"`):''}</div>`:''}${g.versions?.length>1?`<details class="version-history"><summary>Earlier work-detail versions</summary>${g.versions.slice(0,-1).map(v=>`<div class="note"><strong>Version ${v.version}</strong>${detailsGrid([['Scope',v.terms.scope],['Pay',money(v.terms.pay)+' / '+v.terms.basis],['Schedule',v.terms.schedule],['Start',v.terms.start],['General location',v.terms.area+', '+v.terms.city]])}</div>`).join('')}</details>`:''}<p class="caption">Changing any work detail creates a new version and resets both confirmations. Earlier versions are retained in this local record.</p></section>`}
function termsForm(id){const g=engagement(id),a=actor(g),o=opening(g.openingId);if(!g||!a||!['Accepted','Confirmed'].includes(g.status)||blocked(g.workerId,g.employerId)){toast('Accept the conversation and ensure contact is unblocked first.');return}const t=g.terms||{scope:o.description,pay:o.quote?'':o.max,basis:o.basis,schedule:o.type==='One-off task'?o.duration:o.days.join(', ')+' '+o.hoursStart+' – '+o.hoursEnd+' WAT',start:o.type==='One-off task'?o.date:o.start,completionDate:o.date,city:o.city,area:o.area,arrangements:o.type==='One-off task'?o.materials:o.accommodation};main.innerHTML=`<section class="form-page"><button class="back" data-record="${esc(id)}">${icon('close')} Cancel without saving</button><div class="eyebrow">Work record · New version ${g.version+1}</div><h1>Agree the details.</h1><p class="caption">Both sides must confirm this same version before work begins.</p><form id="terms-form" data-id="${esc(id)}" data-actor="${esc(a)}">${textArea('scope','Task scope / responsibilities',t.scope)}<div class="two-fields">${field('pay','Agreed pay (₦)',t.pay,'number','required min="1" max="100000000"')}${select('basis','Payment basis',D.bases,t.basis)}</div>${textArea('schedule','Schedule / agreed time',t.schedule)}${field('start','Start date',t.start,'date','required')}${g.type==='One-off task'?field('completionDate','Completion date',t.completionDate,'date','required'):''}${locationFields(t)}${textArea('arrangements',g.type==='One-off task'?'Materials and costs arrangements':'Accommodation / other arrangements',t.arrangements,false)}${errorBox()}<div class="form-actions"><button class="button secondary" type="button" data-record="${esc(id)}">Cancel</button><button class="button primary">Propose this version</button></div></form></section>`;window.scrollTo({top:0,behavior:'instant'})}
function reviewPanel(g,a){const r=state.reviews.find(r=>r.engagementId===g.id&&r.author===a);return `<section class="panel"><h2>Review this engagement</h2>${r?`<p>${r.rating} / 5 · Your local demo review</p><p>${esc(r.text)}</p>`:`<p>Both sides marked work completed. Leave a review of this engagement only.</p>${button('Write review','review',true,`data-id="${esc(g.id)}"`)}`}</section>`}
function reportModal(id,type){modal('Prepare a private report','Reporting is not connected to an administrator. This creates a private draft you can download; it is not submitted or reviewed.',`<form id="report-form" data-target="${esc(id)}" data-kind="${esc(type)}">${select('reason','Concern',['Misleading information','Unwanted contact','Unsafe request','Other'],'Misleading information')}${textArea('details','What happened? Do not include identity documents or home addresses.','')}${errorBox()}<div class="modal-actions">${button('Cancel','close')}<button class="button primary">Download report draft</button></div></form>`)}
function download(name,content){const url=URL.createObjectURL(new Blob([content],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function privacy(){main.innerHTML=pageHead('Privacy, in plain language.','What this prototype actually does.')+`<article class="panel prose"><h2>Online wallet accounts</h2><p>The Wallet page stores your account, hashed password, session, payment jobs, transactions and reviews in a private server database. Only your own balances and receipts are accessible after sign-in. The current wallet uses test money. NIN and bank OTP are not collected in test mode. Resetting local hiring examples does not erase online wallet records. Email and phone are unverified in the test account flow.</p><h2>Hiring examples: only this browser</h2><p>Profiles, contacts, photos, messages, work records, blocks and reviews are saved in localStorage on this device. They are not shared with other people, a server or another device. Hiring examples have no account access boundary. Wallet accounts are separate and use authenticated sessions with a server database.</p><h2>General location, private contacts</h2><p>Public profile pages use city and general area. Do not enter a home address. Email and phone fields are only displayed in your own editor. Sample profiles contain no private contacts. Email enquiries are available when a worker chooses to share their email. Preparing a draft never sends it.</p><h2>Voluntary nearby location</h2><p>Nearby search requests location only when you choose Use my location. Search coordinates stay in memory, and Clear my location removes them. Update as I move follows your position only while discovery is open. A worker may save a location snapshot locally and remove it; it expires after 24 hours. Public pages show approximate distances and GPS uncertainty, not coordinates or a home address.</p><h2>A demo is not an access-control boundary</h2><p>Anyone using this browser or its developer tools can access local data. Use fictional information on a shared device. The explicit other-party preview exists only to test two-sided journeys, and never displays the other side’s private contact fields.</p><h2>Photos and reports</h2><p>Task photos stay locally with the opening. Upload only images you may share; avoid faces, addresses and sensitive information. Report drafts are downloaded only when you request it, and are not submitted to an administrator.</p><h2>Your choices</h2><p>Hide your worker profile from discovery, edit your entries, remove task photos, block demo contact or reset all current demo data. Previous prototype data uses a separate storage key and is not imported.</p>${button('Clear all LocHire demo data','reset')}<h2>Before live use</h2><p>A pilot needs authenticated accounts, a secured database, server-enforced ownership, controlled contact sharing, a report review team and delivery services. No secret keys are present in the browser.</p></article>`}
function guidelines(){main.innerHTML=pageHead('Community guidelines.','Respect and accountability go both ways.')+`<article class="panel prose"><h2>Be accurate</h2><p>Describe work, experience, pay, hours and materials honestly. Do not claim verification that has not happened. Matching does not establish reliability.</p><h2>Agree before starting</h2><p>Discuss scope, location, pay and schedule. Both sides should confirm the same version. Changes need another confirmation.</p><h2>Respect privacy and choice</h2><p>Do not pressure people to share personal documents or exact home addresses. People may ask questions, decline invitations or stop unwanted contact. Never select or rank people using sensitive personal characteristics.</p><h2>Review real experience</h2><p>Reviews in this prototype are local demo reviews, allowed only after both participants mark an engagement completed. There are no fabricated ratings.</p><h2>Concerns</h2><p>Use Block to prevent further contact in this browser. Report prepares a private downloadable draft, not an unreviewed public accusation. Live moderation and emergency assistance are not available.</p><button class="button secondary" data-page="help">Get help</button></article>`}
function help(){main.innerHTML=pageHead('Help and demo limits.','A working prototype, with clear boundaries.')+`<article class="panel prose"><h2>Try a full journey</h2><p>Create a worker or employer profile. Post a task or role, inspect the other profile and start a conversation. On an engagement record, use “Preview other party in demo” to simulate the counterpart accepting and confirming. Return to your view to complete your side.</p><h2>What works locally</h2><p>Guided profiles and posting, edits and opening status, discovery filters, suitability explanations, invitation responses, local messages, versioned work records, two-party confirmation, completion, blocks, 1–5-star reviews, completed-work history, booking requests, permission-based nearby search and manual email drafts.</p><h2>What is not connected</h2><p>No authentication, shared database, message or email delivery, phone/identity/reference/business checks, live report submission or admin review. The Wallet page has authenticated accounts, persistent test payments and receipts. Real bank transfers, insurance, escrow and identity checks are not connected. All hiring-profile verification statuses remain “Not checked”.</p><h2>Request support</h2><p>You can open your mail app to contact the project owner. LocHire cannot confirm delivery, a response time or emergency support.</p><a class="button secondary" href="mailto:chideraemmanuelokpala@gmail.com?subject=LocHire%20prototype%20support">Email project owner</a><h2>Reporting</h2><p>Download a private report draft from the relevant profile or opening. If you choose to email it, remove unnecessary personal information. There is no connected administrator inbox or review queue.</p><h2>Before a Lagos pilot</h2><p>Connect accounts, server authorization, persistent shared data, notifications, consent controls, optional verification providers and an operational report review process. Test recovery, ownership rules and privacy on the server before collecting real worker information.</p>${button('Reset demo','reset')}</article>`}
function notFound(){main.innerHTML='<div class="empty"><h1>This record is not available.</h1><p>It may belong to another demo participant or no longer exist.</p><button class="button secondary" data-page="home">Go home</button></div>'}
function shortConfirm(title,desc,action,id,extra=''){modal(title,desc,`<div class="modal-actions">${button('Keep as it is','close')}${button('Confirm',action,true,`data-id="${esc(id)}" ${extra}`)}</div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.walletLocalRecord){const record=engagement(b.dataset.walletLocalRecord);if(record&&D.participant(record,ownId()))LocHireWallet.fromLocalRecord(record,opening(record.openingId)?.category);return;}if(b.dataset.page){go(b.dataset.page);return}if(b.dataset.worker){go('worker',b.dataset.worker);return}if(b.dataset.employer){go('employer',b.dataset.employer);return}if(b.dataset.opening){go('opening',b.dataset.opening);return}if(b.dataset.record){const pa=previewActor;go('record',b.dataset.record);previewActor=pa;render();return}if(b.dataset.homeCategory){role='employer';filters={category:b.dataset.homeCategory};search='';go('discover');return}if(b.dataset.report){reportModal(b.dataset.report,b.dataset.reportType);return}if(b.dataset.block){const target=b.dataset.block;if(target===ownId())throw Error('You cannot block your own profile.');shortConfirm('Change contact blocking?','Blocking stops new invitations and messages between these profiles in this local demo. Existing records remain available.','block-final',target);return}const id=b.dataset.id,g=engagement(id);switch(b.dataset.action){case'home':go('home');break;case'role':roleModal();break;case'enter-worker':role='worker';LocHireWallet.selectRole(role).catch(error=>toast(error.message));search='';filters={};go('discover');break;case'enter-employer':role='employer';LocHireWallet.selectRole(role).catch(error=>toast(error.message));search='';filters={};go('discover');break;case'close':dialog.close();break;case'filters':filterModal();break;case'clear-filters':filters={};search='';limit=6;discover();break;case'more':limit+=6;renderDiscovery();break;case'edit-profile':dialog.close();profileWizard();break;case'required-profile':role=b.dataset.role;dialog.close();go('profile');profileWizard();break;case'cancel-wizard':wizard=null;go(route.page==='openings'?'openings':'profile');break;case'wizard-back':wizard.step--;wizardPage();break;case'own-preview':go(role,ownId());break;case'visibility':if(!state.worker)break;shortConfirm('Change profile visibility?',state.worker.published?'Hide your worker profile from local discovery.':'Make your worker profile visible in this browser’s demo discovery.','visibility-final','');break;case'visibility-final':state.worker.published=!state.worker.published;save();dialog.close();render();break;case'post':dialog.close();route={page:'openings',id:''};navigation();postWizard();break;case'edit-opening':dialog.close();route={page:'openings',id:''};postWizard(id);break;case'opening-status':if(opening(id)?.employerId!=='my-employer')throw Error('Only your own openings can be changed.');shortConfirm('Change opening status?',opening(id).status==='Open'?'Close this opening to new conversations. Existing engagements remain.':'Reopen this opening in local discovery.','opening-status-final',id);break;case'opening-status-final':if(opening(id)?.employerId!=='my-employer')throw Error('Only your own openings can be changed.');opening(id).status=opening(id).status==='Open'?'Closed':'Open';save();dialog.close();render();break;case'contact-worker':contactWorker(id);break;case'contact-opening':contactOpening(id);break;case'preview-party':if(!g||!D.participant(g,ownId()))throw Error('Record unavailable.');previewActor=previewActor?null:D.other(g,ownId());recordPage(id);break;case'accept':case'decline':if(blocked(g.workerId,g.employerId))throw Error('Contact is blocked.');D.transition(g,actor(g),b.dataset.action);save();recordPage(id);break;case'arrange-conversation':if(!g||g.status!=='Accepted'||blocked(g.workerId,g.employerId))throw Error('Accept the conversation first.');modal('Arrange a conversation','Propose a date and time in WAT. Discuss and acknowledge it in the thread; no calendar invite is sent.',`<form id="conversation-form" data-id="${esc(id)}">${field('date','Conversation date',g.conversation?.date||'','date',`required min="${D.today()}"`)}${field('time','Conversation time (WAT)',g.conversation?.time||'','time','required')}${errorBox()}<div class="modal-actions">${button('Cancel','close')}<button class="button primary">Save proposed time</button></div></form>`);break;case'terms':termsForm(id);break;case'confirm-terms':shortConfirm('Confirm work details version '+g.version+'?', 'Read the scope, pay, schedule and arrangements on the record. Your confirmation applies only to this version.','confirm-final',id,`data-version="${b.dataset.version}"`);break;case'confirm-final':if(blocked(g.workerId,g.employerId))throw Error('Contact is blocked.');D.confirm(g,actor(g),Number(b.dataset.version));save();dialog.close();recordPage(id);break;case'complete':shortConfirm('Has your side completed the work?','The engagement becomes completed only after both sides mark completion.','complete-final',id);break;case'complete-final':D.transition(g,actor(g),'complete');save();dialog.close();recordPage(id);break;case'cancel-engagement':shortConfirm('Cancel this engagement?','This closes the local conversation and prevents further confirmations.','cancel-final',id);break;case'cancel-final':D.transition(g,actor(g),'cancel');save();dialog.close();recordPage(id);break;case'review':modal('Review this completed engagement','This is a local demo review from the selected participant, not a real public rating.',`<form id="review-form" data-id="${esc(id)}">${select('rating','Your rating',[['','Choose'],[1,'1 - Poor'],[2,'2 - Fair'],[3,'3 - Good'],[4,'4 - Very good'],[5,'5 - Excellent']],'')}${textArea('text','Describe the work and your experience','')}${errorBox()}<div class="modal-actions">${button('Cancel','close')}<button class="button primary">Save demo review</button></div></form>`);break;case'block-final':{const i=state.blocks.findIndex(x=>x.actor===ownId()&&x.target===id);if(i>=0)state.blocks.splice(i,1);else state.blocks.push({actor:ownId(),target:id});save();dialog.close();render();break}case'blocked-list':modal('Blocked profiles','Blocking is local to this browser. It does not contact anyone.',`<div class="stack">${state.blocks.filter(x=>x.actor===ownId()).map(x=>`<button class="list-row" data-block="${esc(x.target)}"><span>${esc(person(x.target)?.name||'Profile')}<small>Click to unblock</small></span>${icon('chevron')}</button>`).join('')||'<p>No blocked profiles.</p>'}</div>`);break;case'reset':shortConfirm('Clear all LocHire demo data?','This removes both the current demo and earlier prototype entries from this browser. This clears local hiring examples only; saved wallet accounts and payments stay on the server.','reset-final','');break;case'reset-final':state=D.seed();localStorage.removeItem(KEY);localStorage.removeItem('lochire-demo-v1');save();wizard=null;filters={};search='';go('home');toast('Local demo reset.');break;}}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='discovery-search'){search=e.target.value;limit=6;renderDiscovery()}if(e.target.name==='flexible'||e.target.name==='quote'){const f=e.target.form;if(f){const required=!e.target.checked;for(const name of e.target.name==='flexible'?['pay']:['min','max'])if(f.elements[name])f.elements[name].required=required}}});
document.addEventListener('change',e=>{if(e.target.id==='compare-opening'){filters.opening=e.target.value;renderDiscovery()}if(e.target.name==='occupation'&&wizard?.kind==='worker'){const f=e.target.form,fd=new FormData(f);for(const [k,v]of fd)if(typeof v==='string')wizard.draft[k]=v.trim();wizard.draft.skills=D.list(wizard.draft.skills);wizardPage()}});
document.addEventListener('submit',async e=>{if(e.target.id.startsWith('wallet-'))return;e.preventDefault();const f=e.target,fd=new FormData(f),d=Object.fromEntries(fd),btn=f.querySelector('button[type="submit"]')||f.querySelector('button.button.primary');try{if(btn){btn.disabled=true;btn.setAttribute('aria-busy','true')}if(f.id==='wizard-form'){await submitWizard(f);return}if(f.id==='filters-form'){if(d.budget&&!d.basis)throw Error('Choose a payment basis to compare rates.');filters={...d,opening:filters.opening};limit=6;dialog.close();discover()}else if(f.id==='contact-worker-form'){const o=opening(d.opening);if(!o||o.employerId!=='my-employer')throw Error('Choose your own opening.');startContact(o,worker(f.dataset.worker),state.employer,ownId(),d.message,d.date,d.time)}else if(f.id==='contact-opening-form'){const o=opening(f.dataset.opening);startContact(o,state.worker,employer(o.employerId),ownId(),d.message)}else if(f.id==='message-form'){const g=engagement(f.dataset.id),a=actor(g);if(blocked(g.workerId,g.employerId))throw Error('Contact is blocked.');D.addMessage(g,a,d.message);save();recordPage(g.id)}else if(f.id==='conversation-form'){const g=engagement(f.dataset.id),a=actor(g);if(!g||!D.participant(g,ownId())||g.status!=='Accepted'||blocked(g.workerId,g.employerId))throw Error('Conversation unavailable.');if(!d.date||!d.time||new Date(`${d.date}T${d.time}:00+01:00`)<=new Date())throw Error('Choose a future date and time in WAT.');g.conversation={date:d.date,time:d.time};D.addMessage(g,a,`Proposed conversation: ${d.date} at ${d.time} WAT. Please confirm in this thread.`);save();dialog.close();recordPage(g.id)}else if(f.id==='terms-form'){const g=engagement(f.dataset.id);if(!g||!D.participant(g,ownId())||f.dataset.actor!==actor(g))throw Error('Return to the engagement before editing.');if(blocked(g.workerId,g.employerId))throw Error('Contact is blocked.');D.propose(g,actor(g),d);save();recordPage(g.id)}else if(f.id==='review-form'){const g=engagement(f.dataset.id);D.review(state,g,actor(g),Number(d.rating),d.text);save();dialog.close();recordPage(g.id)}else if(f.id==='report-form'){if(!d.details?.trim())throw Error('Describe your concern.');download('LocHire-private-report-draft.txt',`PRIVATE REPORT DRAFT - NOT SUBMITTED\nTarget: ${f.dataset.target} (${f.dataset.kind})\nReason: ${d.reason}\nDetails: ${d.details}\n\nNo administrator has received or reviewed this draft.`);dialog.close();toast('Private draft downloaded. It was not submitted.')}}catch(err){formError(err.message)}finally{if(btn?.isConnected){btn.disabled=false;btn.removeAttribute('aria-busy')}}});
dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const items=[...dialog.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(el=>el.getClientRects().length);if(!items.length){e.preventDefault();return}const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===dialog)){e.preventDefault();first.focus()}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
window.addEventListener('hashchange',()=>{const [page,id]=location.hash.slice(1).split('/');if(page&&page!==route.page||id&&id!==route.id){wizard=null;previewActor=null;route={page:page||'home',id:decodeURIComponent(id||'')};render()}});

function stars(value){return `<span class="rating-stars" aria-label="${Number(value).toFixed(1)} out of 5 stars">${[1,2,3,4,5].map(n=>`<span class="rating-star ${value>=n?'filled':value>=n-.5?'half':''}">${icon('star')}</span>`).join('')}</span>`;}
function ratingBadge(id){const r=D.ratingSummary(state,id);return r.count?`<div class="worker-rating">${stars(r.average)}<strong>${r.average.toFixed(1)}</strong><span>${r.count} ${r.count===1?'review':'reviews'} · Local demo</span></div>`:'<div class="worker-rating unrated">No reviews yet</div>';}
function completedWorkHistory(id){const jobs=state.engagements.filter(g=>g.status==='Completed'&&D.participant(g,id));if(!jobs.length)return '<p>No completed engagements recorded yet.</p>';return `<div class="completed-work-list">${jobs.slice().reverse().map(g=>{const r=D.eligibleReviews(state,id).find(r=>r.engagementId===g.id);return `<article class="completed-work-item"><h3>${esc(g.title)}</h3><p>${esc(person(D.other(g,id))?.name||'A participant')} · ${esc(g.type)}</p><p class="caption">${esc(g.terms?.scope||'')}${g.terms?.completionDate?' · Finished '+esc(g.terms.completionDate):''}</p>${r?`<span class="work-history-rating">${stars(r.rating)} ${r.rating} / 5 from this client</span>`:'<span class="caption">Not reviewed yet</span>'}</article>`;}).join('')}</div>`;}
function distanceBadge(w){const info=D.distanceInfo(searchLocation,w.coordinates);if(!info)return `<p class="distance-badge muted">${icon('pin')} ${w.coordinates?'Location expired — ask for an update':'Location not shared'}</p>`;const metres=info.metres<1000?Math.round(info.metres/10)*10+' m':(info.metres/1000).toFixed(1)+' km',accuracy=Math.ceil(info.uncertainty);return `<p class="distance-badge">${icon('pin')} Approx. ${metres} away <span>± ${accuracy} m</span></p>${filters.radius&&info.max>Number(filters.radius)?'<p class="caption">GPS uncertainty overlaps your radius.</p>':''}`;}
function updateLocationStatus(){const el=document.querySelector('#location-status');if(!el)return;el.textContent=locationPending?'Finding your location…':locationError||(searchLocation?`Location ready · GPS accuracy ± ${Math.ceil(searchLocation.accuracy)} m`:'Location is off');el.classList.toggle('location-error',!!locationError);}
function locationPoint(position){const p={lat:position.coords.latitude,lon:position.coords.longitude,accuracy:position.coords.accuracy,at:position.timestamp||Date.now()};if(!D.validLocation(p))throw Error('This device did not return a usable location.');return p;}
function locationFailure(error){locationPending=false;locationError=error.code===1?'Location permission declined. You can still search by city or area.':error.code===3?'Location timed out. Try again outdoors or search by area.':'Location unavailable. You can still search by city or area.';updateLocationStatus();toast(locationError);}
function requestSearchLocation(follow=false){if(!navigator.geolocation){locationFailure({code:2});return;}locationPending=true;locationError='';updateLocationStatus();navigator.geolocation.getCurrentPosition(position=>{try{searchLocation=locationPoint(position);locationPending=false;locationError='';if(!filters.radius)filters.radius='30000';filters.sort='nearest';limit=6;if(route.page==='discover')discover();if(follow)startLocationWatch();}catch(err){locationFailure({code:2});}},locationFailure,{enableHighAccuracy:true,timeout:10000,maximumAge:60000});}
function startLocationWatch(){if(locationWatch!==null||!navigator.geolocation)return;locationWatch=navigator.geolocation.watchPosition(position=>{try{searchLocation=locationPoint(position);locationError='';updateLocationStatus();renderDiscovery();}catch{}},error=>{stopLocationWatch();locationFailure(error);const field=document.querySelector('#follow-location');if(field)field.checked=false;},{enableHighAccuracy:true,timeout:10000,maximumAge:15000});const field=document.querySelector('#follow-location');if(field)field.checked=true;}
function stopLocationWatch(){if(locationWatch!==null&&navigator.geolocation)navigator.geolocation.clearWatch(locationWatch);locationWatch=null;}
function workerLocationPanel(){const w=state.worker;if(!w)return '';const point=D.validLocation(w.coordinates)?w.coordinates:null;return `<section class="panel worker-location-panel"><h2>Nearby discovery & availability</h2><p>Share a location snapshot voluntarily to support nearby searches on this device. It expires after 24 hours. Exact coordinates stay out of public profile views.</p><p class="caption">${point?'Last updated '+new Date(point.at).toLocaleString('en-NG',{timeZone:'Africa/Lagos'})+' WAT · GPS accuracy ± '+Math.ceil(point.accuracy)+' m':'No location shared.'}</p><div class="row-actions"><button class="button secondary" data-service="share-worker-location">${icon('pin')} ${point?'Update shared location':'Share current location'}</button>${point?'<button class="text-button" data-service="remove-worker-location">Remove location</button>':''}</div><label class="check-field"><input id="accepting-bookings" type="checkbox" ${w.acceptingBookings!==false?'checked':''}><span>Accepting booking enquiries</span></label><label class="check-field"><input id="share-contact-email" type="checkbox" ${w.contactEmailShared?'checked':''}><span>Allow my email to be used for enquiries from this local profile</span></label><p class="caption">Sample profiles have no live GPS. This demo does not share records across devices.</p></section>`;}
function requestWorkerLocation(){if(role!=='worker'||!state.worker)return;if(!navigator.geolocation){toast('This device cannot provide a location.');return;}const b=document.querySelector('[data-service="share-worker-location"]');if(b)b.disabled=true;navigator.geolocation.getCurrentPosition(position=>{try{state.worker.coordinates=locationPoint(position);save();render();toast('Location snapshot saved locally. You can remove it at any time.');}catch(err){toast(err.message);if(b?.isConnected)b.disabled=false;}},error=>{if(b?.isConnected)b.disabled=false;toast(error.code===1?'Location permission declined. No location was saved.':'Could not get a location. Try again or keep your general area.');},{enableHighAccuracy:true,timeout:10000,maximumAge:0});}
function bookWorker(id){if(role!=='employer'){role='employer';navigation();}if(!ensureProfile('employer'))return;const w=worker(id);if(!w||blocked(ownId(),id))throw Error('This worker is unavailable for contact.');if(w.acceptingBookings===false)throw Error('This worker is not accepting new bookings.');if(!w.types?.includes('One-off task')){contactWorker(id);return;}modal('Book '+esc(w.name),'This creates a local booking request. The worker must respond, then both sides agree the scope, price and schedule.',`<div class="booking-worker-summary">${ratingBadge(id)}<p>${esc(w.occupation)} · ${esc(w.area)}, ${esc(w.city)}</p>${distanceBadge(w)}</div><form id="booking-form" data-worker="${esc(id)}">${textArea('description','What work do you need?','')}${field('date','Preferred date','','date',`required min="${D.today()}"`)}${field('duration','Estimated duration','','text','required maxlength="100" placeholder="e.g. a few hours, to confirm together"')}<div class="two-fields">${field('city','City',state.employer.city,'text','required maxlength="70"')}${field('area','General area',state.employer.area,'text','required maxlength="90"')}</div><p class="caption">${payText(w)}. Final price and availability must be agreed; do not include a home address.</p>${errorBox()}<div class="modal-actions">${button('Cancel','close')}<button type="submit" class="button primary">Create booking request</button></div></form>`);}
function submitBooking(f,data){const w=worker(f.dataset.worker),e=state.employer;if(role!=='employer'||!e||!w||blocked(e.id,w.id)||w.acceptingBookings===false)throw Error('Create an employer profile and choose an available worker.');const o={id:D.uid(),employerId:e.id,type:'One-off task',category:w.occupation,title:'Booking: '+w.occupation,description:data.description,city:data.city,area:data.area,date:data.date,duration:data.duration,start:data.date,days:[],hoursStart:'',hoursEnd:'',min:0,max:0,basis:'Per task',quote:true,skills:D.list(w.skills),years:0,materials:'Discuss together',accommodation:'Not applicable',photos:[],status:'Open',demo:false};D.validateOpening(o);state.openings.unshift(o);startContact(o,w,e,e.id,`Booking request: ${o.description}\nPreferred date: ${o.date}\nEstimated duration: ${o.duration}\nGeneral area: ${o.area}, ${o.city}\nPlease confirm your availability and quote.`,null,null,'Booking request');toast('Booking request saved locally. Awaiting the simulated worker response; no email was sent.');}
function emailEnquiry(id){const w=worker(id);if(!w||blocked(ownId(),id))throw Error('This profile is unavailable for contact.');const recipient=w.contactEmailShared&&w.email?w.email:'';modal('Email enquiry for '+esc(w.name),'Prepare a draft and open your own mail app. LocHire does not send emails or confirm delivery. Sample workers have no email address.',`<form id="email-enquiry-form">${field('recipient','Recipient email (only if shared with you)',recipient,'email','maxlength="254"')}${field('subject','Subject','LocHire enquiry: '+w.occupation,'text','required maxlength="150"')}${textArea('body','Your enquiry',`Hello ${w.name},\n\nI would like to enquire about ${w.occupation.toLowerCase()} work in my area. Please let me know your availability and estimated price.\n\nThank you.`)}${errorBox()}<div class="modal-actions"><button class="button secondary" type="button" data-service="download-email">Download draft</button><button class="button primary" type="submit">Prepare email</button></div><div id="prepared-email" class="prepared-email" aria-live="polite"></div></form>`);}
function prepareEmail(f){const fd=new FormData(f),email=String(fd.get('recipient')||'').trim(),subject=String(fd.get('subject')||'').trim(),body=String(fd.get('body')||'').trim();if(!subject||!body)throw Error('Add a subject and your enquiry.');if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Enter a valid recipient email.');const href='mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);document.querySelector('#prepared-email').innerHTML=`<p>Draft ready. ${email?'Check the recipient and send it in your mail app.':'Choose the recipient in your mail app before sending.'}</p><a class="button primary" href="${esc(href)}">${icon('mail')} Open email app</a>`;}
document.addEventListener('click',event=>{const b=event.target.closest('button[data-service]');if(!b)return;try{switch(b.dataset.service){case'browse-nearby':role='employer';filters={};search='';go('discover');break;case'locate-search':requestSearchLocation();break;case'forget-location':stopLocationWatch();searchLocation=null;locationError='';delete filters.radius;discover();break;case'share-worker-location':requestWorkerLocation();break;case'remove-worker-location':if(role==='worker'&&state.worker){delete state.worker.coordinates;save();render();}break;case'book-worker':bookWorker(b.dataset.id);break;case'email-worker':emailEnquiry(b.dataset.id);break;case'download-email':{const f=document.querySelector('#email-enquiry-form'),fd=new FormData(f);download('LocHire-email-enquiry-draft.txt',`EMAIL DRAFT - NOT SENT\nTo: ${fd.get('recipient')||'Add a recipient'}\nSubject: ${fd.get('subject')}\n\n${fd.get('body')}`);break;}}}catch(err){toast(err.message);}});
document.addEventListener('change',event=>{const e=event.target;try{if(['nearby-radius','minimum-rating','worker-sort','available-workers'].includes(e.id)){if(e.id==='nearby-radius')filters.radius=e.value;if(e.id==='minimum-rating')filters.rating=e.value;if(e.id==='worker-sort')filters.sort=e.value;if(e.id==='available-workers')filters.available=e.checked?'yes':'';limit=6;renderDiscovery();if((filters.radius||filters.sort==='nearest')&&!searchLocation)toast('Use my location to enable distance search.');}if(e.id==='follow-location'){if(e.checked){if(searchLocation)startLocationWatch();else requestSearchLocation(true);}else stopLocationWatch();}if(e.id==='accepting-bookings'&&role==='worker'&&state.worker){state.worker.acceptingBookings=e.checked;save();}if(e.id==='share-contact-email'&&role==='worker'&&state.worker){state.worker.contactEmailShared=e.checked;save();toast(e.checked?'Email enquiries enabled for your local profile.':'Email sharing switched off.');}}catch(err){toast(err.message);}});
document.addEventListener('submit',event=>{const f=event.target;if(!['booking-form','email-enquiry-form'].includes(f.id))return;event.preventDefault();try{if(f.id==='booking-form')submitBooking(f,Object.fromEntries(new FormData(f)));else prepareEmail(f);}catch(err){formError(err.message);}});
window.addEventListener('pagehide',stopLocationWatch);
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopLocationWatch();const field=document.querySelector('#follow-location');if(field)field.checked=false;}});

if(location.hash){const [page,id]=location.hash.slice(1).split('/');route={page:page||'home',id:decodeURIComponent(id||'')}}render();
